
function plot_results(results)
% PLOT_RESULTS
% Visualizes the main outputs of the Electric Vehicle Digital Twin.
%
% Input:
%   results - Results structure generated by digital_twin_main()

%% Vehicle Speed

figure;

plot(results.time, results.reference_speed, 'LineWidth', 1.5);
hold on;
plot(results.time, results.simulated_speed, 'LineWidth', 1.5);

grid on;

xlabel('Time (s)');
ylabel('Vehicle Speed (m/s)');
title('Reference vs Simulated Vehicle Speed');

legend('Reference Speed', 'Simulated Speed', ...
    'Location', 'best');

%% Battery SOC

figure;

plot(results.time, results.soc * 100, 'LineWidth', 1.5);

grid on;

xlabel('Time (s)');
ylabel('State of Charge (%)');
title('Battery State of Charge');

ylim([0 100]);

%% Vehicle Distance

figure;

plot(results.time, results.distance, 'LineWidth', 1.5);

grid on;

xlabel('Time (s)');
ylabel('Distance (m)');
title('Simulated Vehicle Distance');

%% Motor Torque

figure;

plot(results.time, results.motor_torque, 'LineWidth', 1.5);

grid on;

xlabel('Time (s)');
ylabel('Motor Torque (Nm)');
title('Motor Torque');

end
